-- Isolated local demo fixtures. Payment is simulated, not a real bank transaction.
SET NAMES utf8mb4;
START TRANSACTION;
SET @expert=(SELECT id FROM users WHERE email='expert@onlinelearning.local');
SET @manager=(SELECT id FROM users WHERE email='manager@onlinelearning.local');
SET @student_role=(SELECT id FROM roles WHERE code='STUDENT');
SELECT 'student.full@onlinelearning.local',password_hash,'Học viên kiểm thử full course',@student_role,'ACTIVE',UTC_TIMESTAMP(),1,0,0,UTC_TIMESTAMP(),UTC_TIMESTAMP() FROM users WHERE id=@expert AND NOT EXISTS(SELECT 1 FROM users WHERE email='student.full@onlinelearning.local');
SET @student=(SELECT id FROM users WHERE email='student.full@onlinelearning.local');
SELECT @expert,@manager,'[DEMO-FULL] Java căn bản - Học và kiểm tra kiến thức','Khóa học mẫu hoàn chỉnh: 3 bài học có video, 12 câu hỏi, 2 quiz. Dữ liệu kiểm thử, thanh toán mô phỏng.','Lập trình',299000,'PUBLISHED',UTC_TIMESTAMP(),UTC_TIMESTAMP() WHERE NOT EXISTS(SELECT 1 FROM course WHERE title='[DEMO-FULL] Java căn bản - Học và kiểm tra kiến thức');
SET @course=(SELECT id FROM course WHERE title='[DEMO-FULL] Java căn bản - Học và kiểm tra kiến thức' ORDER BY id LIMIT 1);
SELECT @expert,@course,'COURSE_IMAGE','demo-full/course-cover','image','upload','jpg','https://images.unsplash.com/photo-1515879218367-8466d910aaa4?auto=format&fit=crop&w=1200&q=80',0,UTC_TIMESTAMP() WHERE NOT EXISTS(SELECT 1 FROM media_asset WHERE course_id=@course AND purpose='COURSE_IMAGE');
UPDATE course SET thumbnail_id=(SELECT id FROM media_asset WHERE course_id=@course AND purpose='COURSE_IMAGE' ORDER BY id LIMIT 1) WHERE id=@course AND thumbnail_id IS NULL;
SELECT @expert,@course,'LESSON_VIDEO',public_id,resource_type,delivery_type,format,secure_url,bytes,UTC_TIMESTAMP() FROM media_asset WHERE id=10 AND NOT EXISTS(SELECT 1 FROM media_asset WHERE course_id=@course AND purpose='LESSON_VIDEO');
SET @video=(SELECT id FROM media_asset WHERE course_id=@course AND purpose='LESSON_VIDEO' ORDER BY id LIMIT 1);
SET @q1=(SELECT id FROM questions WHERE course_id=@course AND content='Từ khóa nào khai báo lớp trong Java?' ORDER BY id LIMIT 1);
SET @q2=(SELECT id FROM questions WHERE course_id=@course AND content='Kiểu dữ liệu nào lưu số nguyên?' ORDER BY id LIMIT 1);
SET @q3=(SELECT id FROM questions WHERE course_id=@course AND content='Kiểu dữ liệu nào biểu diễn đúng hoặc sai?' ORDER BY id LIMIT 1);
SET @q4=(SELECT id FROM questions WHERE course_id=@course AND content='Kết quả của 2 + 3 * 4 là bao nhiêu?' ORDER BY id LIMIT 1);
SET @q5=(SELECT id FROM questions WHERE course_id=@course AND content='Toán tử nào kiểm tra hai số bằng nhau?' ORDER BY id LIMIT 1);
SET @q6=(SELECT id FROM questions WHERE course_id=@course AND content='Vòng lặp nào kiểm tra điều kiện trước mỗi lượt?' ORDER BY id LIMIT 1);
SET @q7=(SELECT id FROM questions WHERE course_id=@course AND content='Từ khóa nào thoát khỏi vòng lặp?' ORDER BY id LIMIT 1);
SET @q8=(SELECT id FROM questions WHERE course_id=@course AND content='Từ khóa nào bỏ qua phần còn lại của lượt lặp?' ORDER BY id LIMIT 1);
SET @q9=(SELECT id FROM questions WHERE course_id=@course AND content='Chỉ số phần tử đầu tiên trong mảng là gì?' ORDER BY id LIMIT 1);
SET @q10=(SELECT id FROM questions WHERE course_id=@course AND content='Từ khóa nào tạo đối tượng mới?' ORDER BY id LIMIT 1);
SET @q11=(SELECT id FROM questions WHERE course_id=@course AND content='Lệnh nào in một dòng ra console?' ORDER BY id LIMIT 1);
SET @q12=(SELECT id FROM questions WHERE course_id=@course AND content='Kiểu dữ liệu nào lưu chuỗi ký tự?' ORDER BY id LIMIT 1);
SET @quiz1=(SELECT id FROM quiz WHERE course_id=@course AND title='Quiz 1 - Biến và toán tử' ORDER BY id LIMIT 1);
SET @quiz2=(SELECT id FROM quiz WHERE course_id=@course AND title='Quiz cuối khóa - Java căn bản' ORDER BY id LIMIT 1);
SET @package=(SELECT id FROM course_package WHERE course_id=@course AND duration='ONE_YEAR');
SELECT @student,@course,@package,'ACTIVE',299000,'DEMO ONLY - simulated payment, no bank transaction',UTC_TIMESTAMP(),UTC_TIMESTAMP(),DATE_SUB(UTC_TIMESTAMP(),INTERVAL 1 HOUR),DATE_ADD(UTC_TIMESTAMP(),INTERVAL 1 YEAR),'1 năm','ONE_YEAR',299000,0,0,12,0,'Học viên kiểm thử full course','student.full@onlinelearning.local','0900000000' WHERE NOT EXISTS(SELECT 1 FROM course_registration WHERE student_id=@student AND course_id=@course);
SET @registration=(SELECT id FROM course_registration WHERE student_id=@student AND course_id=@course ORDER BY id LIMIT 1);
SET @payment=(SELECT id FROM payment WHERE registration_id=@registration);
COMMIT;
SELECT @student AS student_id,@course AS course_id,@registration AS registration_id,@video AS video_id,@quiz1 AS lesson_quiz_id,@quiz2 AS final_quiz_id;
